set-variable.value:
#[output application/java --- {
	status: 'IN_PROGRESS',
	correlationId: vars.correlationId,
	startedAt: now() as String {format: 'yyyy-MM-dd\'T\'HH:mm:ssXXX'}
}]

ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
if (vars.dcOverallSummaryJson is Array)
	do {
		// Filter out empty/null entries from scatter-gather Array
		var validEntries = (vars.dcOverallSummaryJson default []) filter ((item) -> item != null and item != "")
		// Parse each JSON string and collect all documents arrays
		var allDocuments = validEntries flatMap ((entry) ->
			(read(entry, "application/json")).documents default []
		)
		---
		if (sizeOf(allDocuments) > 0)
			write({ documents: allDocuments }, "application/json")
		else null
	}
else
	// Already a String (no scatter-gather corruption), use as-is
	vars.dcOverallSummaryJson

json-logger:logger.json-logger:content:
#[output application/json
---
{
	correlationId: vars.correlationId,
	subFlowName: "download-pdf-subflow",
	step: "DOWNLOAD_START",
	contentVersionId: vars.contentVersion.Id,
	expectedSizeBytes: vars.contentVersion.ContentSize,
	expectedSizeMb: (vars.contentVersion.ContentSize / 1048576) as Number {format: "0.00"}
}]

salesforce:create.salesforce:records:
#[[{
	Title: vars.partFileName,
	PathOnClient: vars.partFileName ++ '.pdf',
	VersionData: vars.partContentBase64
}]]

#[[{
	ContentDocumentId: vars.newContentDocumentId,
	LinkedEntityId: vars.claimId,
	ShareType: 'V',
	Visibility: 'AllUsers'
}]]

ee:message.ee:set-payload:
%dw 2.0
output multipart/form-data
---
{
	parts : {
		file : {
			headers : {
				"Content-Disposition" : {
					"name": "file",
					"filename": vars.partFileName ++ ".pdf",
					"subtype": "form-data"
				},
				"Content-Type" : "application/pdf"
			},
			content : vars.partContent
		}
	}
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java

var successResults = vars.allIdpResults.results filter $.status == "SUCCESS"

// Parse overallSummary.value JSON from each part and collect documents
var allParsedSummaries = successResults map ((result) ->
	do {
		var raw = result.extractedData.fields.overallSummary.value default "{}"
		---
		read(raw, "application/json")
	}
) filter ($ != null)

// Combine all documents arrays from all parts
var combinedDocuments = allParsedSummaries flatMap ($.documents default [])

// Combine metadata from all parts
var combinedMetadata = {
	totalFilesProcessed: sizeOf(successResults),
	totalPages: sum(allParsedSummaries map ($.metadata.totalPages default 0)),
	totalDocuments: sizeOf(combinedDocuments),
	partCount: sizeOf(successResults)
}

---
{
	claimId: vars.allIdpResults.claimId,
	sourceContentDocumentId: vars.allIdpResults.sourceContentDocumentId,
	correlationId: vars.allIdpResults.correlationId,
	totalParts: vars.allIdpResults.totalParts,
	mergedAt: now(),

	// Combined overallSummary from all parts
	combinedIdpSummary: {
		documents: combinedDocuments,
		metadata: combinedMetadata
	},

	// Keep individual part results for reference
	partResults: vars.allIdpResults.results map {
		partNumber: $.partNumber,
		contentDocumentId: $.contentDocumentId,
		status: $.status,
		documentName: $.extractedData.documentName default ""
	},

	// Summary statistics
	summary: {
		totalPartsProcessed: vars.allIdpResults.processedParts,
		successfulParts: sizeOf(successResults),
		failedParts: sizeOf(vars.allIdpResults.results filter $.status == "FAILED"),
		totalDocuments: sizeOf(combinedDocuments),
		totalPages: sum(allParsedSummaries map ($.metadata.totalPages default 0))
	}
}

%dw 2.0
output application/java
var raw = vars.idpExtractedData.extractedData.fields.overallSummary.value default "{}"
var parsed = read(raw, "application/json")
var docs = parsed.documents default []
var fieldKeys = ["documentType", "patientName", "dateOfBirth", "provider",
	"referringDoctor", "readingDoctor", "dateOfService", "chiefComplaint",
	"pastMedicalHistory", "treatmentPlan", "diagnosis", "nextOfficeVisit",
	"workStatus", "conditionProgression", "summary"]
---
docs flatMap ((doc, docIdx) ->
	fieldKeys map ((fieldKey) -> {
		key: "doc_" ++ (doc.sequenceNumber default (docIdx + 1)) ++ "." ++ fieldKey,
		value: doc[fieldKey] as String default ""
	}) filter ($.value != "" and $.value != "null")
)
